package org.eclipse.rdf4j.common.iteration;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.net.URL;
import java.net.URLClassLoader;
import java.util.Arrays;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

import org.junit.jupiter.api.Test;

class CloseableIterationInitializationTest {

	private static final String PACKAGE = "org.eclipse.rdf4j.common.iteration.";
	private static final String CLOSEABLE_ITERATION = PACKAGE + "CloseableIteration";
	private static final String EMPTY_ITERATION = PACKAGE + "EmptyIteration";
	private static final String ITERATION_CONSTANTS = PACKAGE + "IterationConstants";

	@Test
	void holderInitializationDoesNotWaitForEmptyIteration() throws Exception {
		assertIndependentInitialization("IterationConstants");
	}

	@Test
	void unionInitializationDoesNotWaitForEmptyIteration() throws Exception {
		assertIndependentInitialization("DualUnionIteration");
	}

	@Test
	void interfaceInitializationDoesNotWaitForEmptyIteration() throws Exception {
		assertIndependentInitialization("CloseableIteration");
	}

	@Test
	void abstractIterationInitializationDoesNotWaitForEmptyIteration() throws Exception {
		assertIndependentInitialization("AbstractCloseableIteration");
	}

	@Test
	void subclassInitializationDoesNotWaitForEmptyIteration() throws Exception {
		assertIndependentInitialization("SingletonIteration");
	}

	@Test
	void emptyIterationCanBeInitializedFirst() throws Exception {
		assertIndependentInitialization("EmptyIteration");
	}

	@Test
	void sharedConstantCanBeAccessedBeforeInterfaceInitialization() throws Exception {
		assertIndependentInitialization("CloseableIteration", true);
	}

	private void assertIndependentInitialization(String firstClass) throws Exception {
		assertIndependentInitialization(firstClass, false);
	}

	private void assertIndependentInitialization(String firstClass, boolean constantFirst) throws Exception {
		ExecutorService initializer = Executors.newSingleThreadExecutor(runnable -> {
			Thread thread = new Thread(runnable, "empty-iteration-initializer");
			thread.setDaemon(true);
			return thread;
		});
		try (InitializationClassLoader loader = new InitializationClassLoader(initializer)) {
			Object constant = constantFirst ? sharedConstant(loader) : null;
			assertDoesNotThrow(() -> Class.forName(PACKAGE + firstClass, true, loader));
			assertDoesNotThrow(() -> Class.forName(EMPTY_ITERATION, true, loader));
			Object initializedConstant = sharedConstant(loader);
			assertSame(loader.loadClass(EMPTY_ITERATION), initializedConstant.getClass());
			if (constantFirst) {
				assertSame(constant, initializedConstant);
			}
		} finally {
			// A failed initializer releases its initialization lock, so even the failing regression can finish.
			initializer.shutdownNow();
			assertTrue(initializer.awaitTermination(10, TimeUnit.SECONDS), "Initializer did not terminate");
		}
	}

	private Object sharedConstant(ClassLoader loader) throws ReflectiveOperationException {
		return Class.forName(ITERATION_CONSTANTS, false, loader).getField("EMPTY_STATEMENT_ITERATION").get(null);
	}

	/**
	 * Use fresh production classes for each initialization order. When the constant holder (or an accidentally
	 * reintroduced interface initializer) requests EmptyIteration, let another thread initialize that class first. The
	 * other thread cannot finish if it needs the initializer that is still running. A bounded failure releases that
	 * initialization lock, without leaving deadlocked threads behind or modifying production bytecode.
	 */
	private static final class InitializationClassLoader extends URLClassLoader {

		static {
			registerAsParallelCapable();
		}

		private final ExecutorService initializer;
		private final Thread initiatingThread = Thread.currentThread();

		private InitializationClassLoader(ExecutorService initializer) {
			super(new URL[] { CloseableIteration.class.getProtectionDomain().getCodeSource().getLocation() },
					CloseableIterationInitializationTest.class.getClassLoader());
			this.initializer = initializer;
		}

		@Override
		protected Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
			if (!name.startsWith(PACKAGE)) {
				return super.loadClass(name, resolve);
			}
			Class<?> result;
			synchronized (getClassLoadingLock(name)) {
				result = findLoadedClass(name);
				if (result == null) {
					result = findClass(name);
				}
				if (resolve) {
					resolveClass(result);
				}
			}
			// Do not hold a class-loading lock while coordinating the separate initialization thread.
			if (name.equals(EMPTY_ITERATION) && Thread.currentThread() == initiatingThread
					&& Arrays.stream(initiatingThread.getStackTrace())
							.anyMatch(frame -> (frame.getClassName().equals(CLOSEABLE_ITERATION)
									|| frame.getClassName().equals(ITERATION_CONSTANTS))
									&& frame.getMethodName().equals("<clinit>"))) {
				try {
					initializer.submit(() -> Class.forName(name, true, this)).get(5, TimeUnit.SECONDS);
				} catch (TimeoutException e) {
					throw new AssertionError("Shared iteration initialization waits for EmptyIteration, whose "
							+ "initialization waits for the shared iteration initializer", e);
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new AssertionError("Interrupted while initializing EmptyIteration", e);
				} catch (ExecutionException e) {
					throw new AssertionError("Could not initialize EmptyIteration", e.getCause());
				}
			}
			return result;
		}
	}
}
